def solve(payload):
    import math
    q = payload["quaternion"]
    norm = math.sqrt(sum(x*x for x in q))
    if norm <= 1e-12:
        return {"error": "zero_quaternion"}
    w, x, y, z = [v/norm for v in q]
    matrix = [
        [1-2*(y*y+z*z), 2*(x*y-z*w), 2*(x*z+y*w)],
        [2*(x*y+z*w), 1-2*(x*x+z*z), 2*(y*z-x*w)],
        [2*(x*z-y*w), 2*(y*z+x*w), 1-2*(x*x+y*y)],
    ]
    return {"points": [[sum(row[j]*p[j] for j in range(3))+payload["translation"][i] for i, row in enumerate(matrix)] for p in payload["points"]]}
